CREATE TABLE curve_local_plan_review_coverage (edition text PRIMARY KEY, catalog_digest text NOT NULL);
ALTER TABLE curve_local_plan_submission ADD CONSTRAINT curve_lpls_parent_scope_fk FOREIGN KEY(workspace_id,initiative_id,plan_revision_id) REFERENCES curve_local_plan_revision(workspace_id,initiative_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE curve_local_plan_decision ADD CONSTRAINT curve_lpld_parent_scope_fk FOREIGN KEY(workspace_id,initiative_id,plan_submission_id) REFERENCES curve_local_plan_submission(workspace_id,initiative_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION curve_lpls_insert_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE p jsonb:=NEW.payload; plan curve_local_plan_revision%ROWTYPE; subject curve_local_plan_submission%ROWTYPE; prd curve_local_prd_submission%ROWTYPE;
BEGIN
 PERFORM curve_scope_reopening_verify_coverage();
 IF NOT curve_sprd_shape(p, '{"additionalProperties":false,"properties":{"content_digest":{"pattern":"^sha256:[0-9a-f]{64}$","type":"string"},"digest":{"pattern":"^sha256:[0-9a-f]{64}$","type":"string"},"id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"initiative_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"initiative_version":{"maximum":9007199254740991,"minimum":1,"type":"integer"},"plan_revision_digest":{"pattern":"^sha256:[0-9a-f]{64}$","type":"string"},"plan_revision_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"plan_version":{"maximum":9007199254740991,"minimum":1,"type":"integer"},"prd_decision_digest":{"pattern":"^sha256:[0-9a-f]{64}$","type":"string"},"prd_decision_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"prd_submission_digest":{"pattern":"^sha256:[0-9a-f]{64}$","type":"string"},"prd_submission_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"schema_version":{"const":"curve.local-plan-submission/v1-candidate"},"submitted_at":{"pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(\\.\\d{1,6})?Z$","type":"string"},"submitted_by":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"technical_approver_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"technical_gate_assignment_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"workspace_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"}},"required":["content_digest","digest","id","initiative_id","initiative_version","plan_revision_digest","plan_revision_id","plan_version","prd_decision_digest","prd_decision_id","prd_submission_digest","prd_submission_id","schema_version","submitted_at","submitted_by","technical_approver_id","technical_gate_assignment_id","workspace_id"],"type":"object"}'::jsonb) THEN RAISE EXCEPTION 'LOCAL_PLAN_REVIEW_SHAPE' USING ERRCODE='23514'; END IF;
 IF p->>'id' IS DISTINCT FROM NEW.id::text OR p->>'workspace_id' IS DISTINCT FROM NEW.workspace_id::text OR p->>'initiative_id' IS DISTINCT FROM NEW.initiative_id::text OR p->'initiative_version' IS DISTINCT FROM to_jsonb(NEW.initiative_version) OR p->>'digest' IS DISTINCT FROM NEW.digest OR curve_sprd_digest(p-'digest') IS DISTINCT FROM NEW.digest THEN RAISE EXCEPTION 'LOCAL_PLAN_REVIEW_IDENTITY' USING ERRCODE='23514'; END IF;
 SELECT * INTO plan FROM curve_local_plan_revision WHERE id=NEW.plan_revision_id AND workspace_id=NEW.workspace_id AND initiative_id=NEW.initiative_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'LOCAL_PLAN_REVIEW_PARENT' USING ERRCODE='23514'; END IF;
 SELECT * INTO prd FROM curve_local_prd_submission WHERE id=plan.prd_submission_id;
 IF p->>'plan_revision_id' IS DISTINCT FROM plan.id::text OR p->>'plan_revision_digest' IS DISTINCT FROM plan.digest OR p->'plan_version' IS DISTINCT FROM to_jsonb(plan.version) OR p->>'content_digest' IS DISTINCT FROM plan.payload->'snapshot'->>'digest'
 OR p->>'prd_submission_id' IS DISTINCT FROM plan.prd_submission_id::text OR p->>'prd_decision_id' IS DISTINCT FROM plan.prd_decision_id::text OR p->>'prd_submission_digest' IS DISTINCT FROM plan.payload->>'prd_submission_digest' OR p->>'prd_decision_digest' IS DISTINCT FROM plan.payload->>'prd_decision_digest'
 OR p->>'technical_gate_assignment_id' IS DISTINCT FROM prd.payload->'reviewers'->0->>'gate_assignment_id' OR p->>'technical_approver_id' IS DISTINCT FROM prd.payload->'reviewers'->0->>'approver_user_id'
 OR p->>'submitted_by' IS DISTINCT FROM plan.payload->>'uploaded_by' OR NEW.initiative_version<plan.initiative_version OR (p->>'submitted_at')::timestamptz<(plan.payload->>'uploaded_at')::timestamptz THEN RAISE EXCEPTION 'LOCAL_PLAN_REVIEW_SUBJECT' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER curve_lpls_insert BEFORE INSERT ON curve_local_plan_submission FOR EACH ROW EXECUTE FUNCTION curve_lpls_insert_guard();
CREATE TRIGGER curve_lpls_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON curve_local_plan_submission FOR EACH STATEMENT EXECUTE FUNCTION curve_mpd2_immutable();
CREATE FUNCTION curve_lpld_insert_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE p jsonb:=NEW.payload; plan curve_local_plan_revision%ROWTYPE; subject curve_local_plan_submission%ROWTYPE; prd curve_local_prd_submission%ROWTYPE;
BEGIN
 PERFORM curve_scope_reopening_verify_coverage();
 IF NOT curve_sprd_shape(jsonb_set(p,'{feedback}','null'::jsonb), '{"additionalProperties":false,"properties":{"decided_at":{"pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d(\\.\\d{1,6})?Z$","type":"string"},"decided_by":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"digest":{"pattern":"^sha256:[0-9a-f]{64}$","type":"string"},"feedback":{"type":"null"},"id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"initiative_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"initiative_version":{"maximum":9007199254740991,"minimum":1,"type":"integer"},"plan_revision_digest":{"pattern":"^sha256:[0-9a-f]{64}$","type":"string"},"plan_revision_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"plan_submission_digest":{"pattern":"^sha256:[0-9a-f]{64}$","type":"string"},"plan_submission_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"schema_version":{"const":"curve.local-plan-decision/v1-candidate"},"state":{"enum":["APPROVED","CHANGES_REQUESTED"]},"technical_gate_assignment_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"},"workspace_id":{"pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$","type":"string"}},"required":["decided_at","decided_by","digest","feedback","id","initiative_id","initiative_version","plan_revision_digest","plan_revision_id","plan_submission_digest","plan_submission_id","schema_version","state","technical_gate_assignment_id","workspace_id"],"type":"object"}'::jsonb) THEN RAISE EXCEPTION 'LOCAL_PLAN_REVIEW_SHAPE' USING ERRCODE='23514'; END IF;
 IF p->>'id' IS DISTINCT FROM NEW.id::text OR p->>'workspace_id' IS DISTINCT FROM NEW.workspace_id::text OR p->>'initiative_id' IS DISTINCT FROM NEW.initiative_id::text OR p->'initiative_version' IS DISTINCT FROM to_jsonb(NEW.initiative_version) OR p->>'digest' IS DISTINCT FROM NEW.digest OR curve_sprd_digest(p-'digest') IS DISTINCT FROM NEW.digest THEN RAISE EXCEPTION 'LOCAL_PLAN_REVIEW_IDENTITY' USING ERRCODE='23514'; END IF;
 SELECT * INTO subject FROM curve_local_plan_submission WHERE id=NEW.plan_submission_id AND workspace_id=NEW.workspace_id AND initiative_id=NEW.initiative_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'LOCAL_PLAN_REVIEW_PARENT' USING ERRCODE='23514'; END IF;
 IF p->>'plan_submission_id' IS DISTINCT FROM subject.id::text OR p->>'plan_submission_digest' IS DISTINCT FROM subject.digest OR p->>'plan_revision_id' IS DISTINCT FROM subject.payload->>'plan_revision_id' OR p->>'plan_revision_digest' IS DISTINCT FROM subject.payload->>'plan_revision_digest'
 OR p->>'technical_gate_assignment_id' IS DISTINCT FROM subject.payload->>'technical_gate_assignment_id' OR p->>'decided_by' IS DISTINCT FROM subject.payload->>'technical_approver_id' OR NEW.initiative_version<subject.initiative_version OR (p->>'decided_at')::timestamptz<(subject.payload->>'submitted_at')::timestamptz OR p->>'state' IS DISTINCT FROM NEW.state THEN RAISE EXCEPTION 'LOCAL_PLAN_REVIEW_DECISION' USING ERRCODE='23514'; END IF;
 IF NOT (p ? 'feedback') OR (NEW.state='APPROVED' AND p->'feedback' IS DISTINCT FROM 'null'::jsonb) OR (NEW.state='CHANGES_REQUESTED' AND NOT curve_sprd_shape(p->'feedback','{"type":"object","additionalProperties":false,"required":["object_id","digest","size_bytes","media_type"],"properties":{"object_id":{"type":"string","pattern":"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"},"digest":{"type":"string","pattern":"^sha256:[0-9a-f]{64}$"},"size_bytes":{"type":"integer","minimum":1,"maximum":16384},"media_type":{"const":"text/plain"}}}'::jsonb)) THEN RAISE EXCEPTION 'LOCAL_PLAN_REVIEW_FEEDBACK' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER curve_lpld_insert BEFORE INSERT ON curve_local_plan_decision FOR EACH ROW EXECUTE FUNCTION curve_lpld_insert_guard();
CREATE TRIGGER curve_lpld_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON curve_local_plan_decision FOR EACH STATEMENT EXECUTE FUNCTION curve_mpd2_immutable();
CREATE OR REPLACE FUNCTION public.curve_scope_reopening_verify_coverage()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE expected text; actual text;
BEGIN
 IF (SELECT count(*) FROM curve_scope_reopening_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_scope_reopening_coverage
  WHERE edition='CURVE_PRE_PLAN_C2B_V1' AND catalog_digest='sha256:e44c580ea214e03b315c2b14c038cb14ae5d99fa8a60115e82d6b5841ac177a7')
  OR (SELECT count(*) FROM curve_manual_plan_v2_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_manual_plan_v2_coverage
  WHERE edition='CURVE_MANUAL_PLAN_DRAFT_RECONSTRUCTION_V2' AND catalog_digest='sha256:4f0c5e4b1ba7c5e00a3cf35fa55092cb71f571fa34a564f2859af7a46b0b67e8') THEN
  RAISE EXCEPTION 'MANUAL_GATE2_PREDECESSOR_SEAL_INVALID' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM curve_manual_gate2_v2_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_manual_gate2_v2_coverage WHERE edition='CURVE_MANUAL_GATE2_RECONSTRUCTION_V2' AND catalog_digest='sha256:4d33761d55c0f0cb509af13a729cdb6a7479c7b8ca662fc843f856bce33adb08') THEN
 RAISE EXCEPTION 'TWO_STAGE_PREDECESSOR_SEAL_INVALID' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM curve_two_stage_v2_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_two_stage_v2_coverage WHERE edition='CURVE_TWO_STAGE_REVIEW_V2' AND catalog_digest='sha256:fb8f201929aac3461836becdecdde3b29996e52e6aea6ed48c2be6035c1083ef') THEN
 RAISE EXCEPTION 'SCOPED_V2_PREDECESSOR_SEAL_INVALID' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM curve_scoped_v2_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_scoped_v2_coverage WHERE edition='CURVE_SCOPED_PRD_V2' AND catalog_digest='sha256:c14b6221600c6e6be301cc3a36d26cbeb4b3c85e3d904f42e6cbb5e39e67f207') THEN
 RAISE EXCEPTION 'MANUAL_V3_PREDECESSOR_SEAL_INVALID' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM curve_manual_plan_v3_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_manual_plan_v3_coverage WHERE edition='CURVE_MANUAL_PLAN_V3' AND catalog_digest='sha256:1e67c1cedc9bd5529f060b3b6a726291163cc2e5d8634fe2e11b3fe33c2d7866') THEN RAISE EXCEPTION 'TECHNICAL_V3_PREDECESSOR_SEAL_INVALID' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM curve_manual_gate2_v3_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_manual_gate2_v3_coverage WHERE edition='CURVE_MANUAL_GATE2_V3' AND catalog_digest='sha256:8b846ec66b306ffc5c95b52818c5bb03acadadde679df7b678da4f3afedc0e64') THEN RAISE EXCEPTION 'LOCAL_PRD_PREDECESSOR_SEAL_INVALID' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM curve_local_prd_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_local_prd_coverage WHERE edition='CURVE_LOCAL_PRD_SOURCE_V1' AND catalog_digest='sha256:493f45a0eadfd45263212043ec835fd996ac1968ad2bdeb6e25d23b0657590d3') THEN RAISE EXCEPTION 'LOCAL_PRD_COMMAND_PREDECESSOR_INVALID' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM curve_local_prd_command_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_local_prd_command_coverage WHERE edition='CURVE_LOCAL_PRD_COMMAND_V1' AND catalog_digest='sha256:5a0d96f6556657552da753e3f81d79004c0b84622aad7f89789f1a7fa7e1202d') THEN RAISE EXCEPTION 'LOCAL_REVIEW_PREDECESSOR_INVALID' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM curve_local_prd_review_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_local_prd_review_coverage WHERE edition='CURVE_LOCAL_PRD_REVIEW_V1' AND catalog_digest='sha256:72373212877c9f6510b8fec3fa9881d1f9167e5f703ade011a54d81a8b6c519c') THEN RAISE EXCEPTION 'LOCAL_LIFECYCLE_PREDECESSOR_INVALID' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM curve_local_prd_lifecycle_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_local_prd_lifecycle_coverage WHERE edition='CURVE_LOCAL_PRD_LIFECYCLE_V1' AND catalog_digest='sha256:686647dc47a2fe04fbc427615338a69f2b6574d6d3c3566450022357006b371a') THEN RAISE EXCEPTION 'LOCAL_REVIEW_COMMAND_PREDECESSOR_INVALID' USING ERRCODE='23514'; END IF;
 IF (SELECT count(*) FROM curve_local_review_command_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_local_review_command_coverage WHERE edition='CURVE_LOCAL_REVIEW_COMMAND_V1' AND catalog_digest='sha256:61e61f1f432642210b96957bd10ae4c73b907db171c79978090c7f202c6c1b27') THEN RAISE EXCEPTION 'LOCAL_PLAN_PREDECESSOR_INVALID'; END IF;
 IF (SELECT count(*) FROM curve_local_plan_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_local_plan_coverage WHERE edition='CURVE_LOCAL_PLAN_REVISION_V1' AND catalog_digest='sha256:d6fc20764bb94c03248733d050de7cf9a65688ae7589d05c5dd98a7a25e26122') THEN RAISE EXCEPTION 'LOCAL_PLAN_UPLOAD_PREDECESSOR_INVALID'; END IF;
 IF (SELECT count(*) FROM curve_local_plan_upload_coverage)<>1 OR NOT EXISTS(SELECT 1 FROM curve_local_plan_upload_coverage WHERE edition='CURVE_LOCAL_PLAN_UPLOAD_V1' AND catalog_digest='sha256:ee2a07a279b1f5a6f1c3346dc716644015e4469e3db5938a51e37995c372487c') THEN RAISE EXCEPTION 'LOCAL_PLAN_REVIEW_PREDECESSOR_INVALID'; END IF;
 SELECT catalog_digest INTO expected FROM curve_local_plan_review_coverage WHERE edition='CURVE_LOCAL_PLAN_REVIEW_V1';
 actual:='sha256:'||encode(sha256(convert_to(curve_scope_reopening_catalog()::text,'UTF8')),'hex');
 IF expected IS NULL OR expected IS DISTINCT FROM actual OR (SELECT count(*) FROM curve_local_plan_review_coverage)<>1 THEN
  RAISE EXCEPTION 'LOCAL_PRD_COMMAND_COVERAGE_UNAVAILABLE' USING ERRCODE='23514'; END IF;
END $function$;
